  /* ============================ s_konum: görseller ============================ */
  const yonE = v => v === 0 ? "0°" : Math.abs(v) + "° " + (v > 0 ? "K" : "G");
  const yonB = v => v === 0 ? "0°" : Math.abs(v) + "° " + (v > 0 ? "D" : "B");
  /* Enlem–boylam ağı: enlemler −40…40, boylamlar −60…60 (20'şer derece). noktalar: [{ad, e, b}] */
  function ag(noktalar, { ekvator = true } = {}) {
    const W = 560, H = 300, x0 = 90, y0 = 30, dx = 70, dy = 55;
    const xk = b => x0 + (b + 60) / 20 * dx, yk = e => y0 + (40 - e) / 20 * dy;
    let ic = `<rect class="g-yumusak" x="${xk(-60)}" y="${yk(40)}" width="${xk(60) - xk(-60)}" height="${yk(-40) - yk(40)}"/>`;
    for (let e = -40; e <= 40; e += 20) ic += `<line class="${e === 0 && ekvator ? "g-cizgi" : "g-ince"}" x1="${xk(-60)}" x2="${xk(60)}" y1="${yk(e)}" y2="${yk(e)}"${e === 0 ? ' stroke-width="2"' : ""}/>` + G.yazi(xk(-60) - 8, yk(e) + 4, yonE(e), { a: "end", k: 1 });
    for (let b = -60; b <= 60; b += 20) ic += `<line class="${b === 0 ? "g-cizgi" : "g-ince"}" y1="${yk(40)}" y2="${yk(-40)}" x1="${xk(b)}" x2="${xk(b)}"${b === 0 ? ' stroke-width="2"' : ""}/>` + G.yazi(xk(b), yk(-40) + 20, yonB(b), { k: 1 });
    if (ekvator) ic += G.yazi(xk(60) - 4, yk(0) - 6, "Ekvator", { a: "end", k: 1 });
    ic += G.yazi(xk(0) + 4, yk(40) - 8, "Başlangıç meridyeni", { a: "start", k: 1 });
    noktalar.forEach(n => { ic += `<circle class="g-d" cx="${xk(n.b)}" cy="${yk(n.e)}" r="7"/>` + G.yazi(xk(n.b) + 10, yk(n.e) - 8, n.ad, { a: "start", b: 1 }); });
    return G.svg(W, H, ic, "enlem ve boylam ağı üzerinde noktalar");
  }
  /* Türkiye'nin şematik haritası, 36°–42° K enlemleri ve 26°–45° D boylamlarıyla */
  const TR_SINIR = [[26.0, 40.6], [26.6, 41.7], [28.0, 42.0], [29.1, 41.2], [31.2, 41.1], [33.5, 42.0], [35.2, 42.0], [36.6, 41.3], [38.3, 40.9], [40.0, 40.9], [41.5, 41.5], [43.0, 41.2], [43.6, 40.9], [44.8, 39.7], [44.3, 38.3], [44.8, 37.2], [42.3, 37.1], [40.0, 36.9], [38.0, 36.8], [36.6, 36.8], [36.2, 35.9], [35.8, 36.6], [34.6, 36.8], [32.6, 36.1], [30.6, 36.5], [29.6, 36.2], [28.2, 36.7], [27.4, 37.0], [26.8, 38.3], [26.3, 39.0], [26.2, 39.5], [26.6, 40.3]];
  function turkiye({ yonler = true, nokta = null } = {}) {
    const W = 620, H = 320, xk = b => 40 + (b - 25) * 27, yk = e => 30 + (43 - e) * 32;
    let ic = `<rect class="g-yumusak" x="${xk(25)}" y="${yk(43)}" width="${xk(46) - xk(25)}" height="${yk(35) - yk(43)}"/>`;
    for (let e = 36; e <= 42; e += 2) ic += `<line class="g-ince" x1="${xk(25)}" x2="${xk(46)}" y1="${yk(e)}" y2="${yk(e)}"/>` + G.yazi(xk(25) - 4, yk(e) + 4, e + "° K", { a: "end", k: 1 });
    for (const b of [26, 30, 35, 40, 45]) ic += `<line class="g-ince" x1="${xk(b)}" x2="${xk(b)}" y1="${yk(43)}" y2="${yk(35)}"/>` + G.yazi(xk(b), yk(35) + 18, b + "° D", { k: 1 });
    ic += `<polygon class="g-b g-cizgi" fill-opacity="0.7" stroke-width="1.5" points="${TR_SINIR.map(([b, e]) => xk(b).toFixed(1) + "," + yk(e).toFixed(1)).join(" ")}"/>`;
    if (yonler) ic += G.yazi(xk(34), yk(42.6), "Karadeniz", { k: 1 }) + G.yazi(xk(31), yk(35.5), "Akdeniz", { k: 1 }) + G.yazi(xk(25.6), yk(38.2), "Ege", { k: 1, a: "start" });
    if (nokta) ic += `<circle class="g-d" cx="${xk(nokta.b)}" cy="${yk(nokta.e)}" r="6"/>` + G.yazi(xk(nokta.b) + 8, yk(nokta.e) - 6, nokta.ad, { a: "start", b: 1 });
    return G.svg(W, H, ic, "Türkiye'nin enlem ve boylam aralığını gösteren şematik harita");
  }
  /* Şematik dünya haritası: kıtalar elips/çokgen, harfli ya da adlı etiketler. etiket: {Asya:"A", ...} */
  const KITA = {
    "Kuzey Amerika": [[40, 30], [170, 25], [190, 70], [140, 120], [110, 150], [75, 110], [35, 70]],
    "Güney Amerika": [[125, 138], [178, 148], [192, 190], [150, 280], [130, 285], [112, 195]],
    "Avrupa": [[255, 45], [325, 35], [335, 80], [300, 95], [265, 92], [250, 70]],
    "Afrika": [[255, 110], [335, 105], [365, 150], [340, 230], [305, 250], [290, 190], [250, 150]],
    "Asya": [[335, 30], [530, 25], [555, 80], [500, 140], [440, 165], [385, 130], [340, 95]],
    "Avustralya": [[465, 210], [535, 205], [545, 250], [480, 260]],
    "Antarktika": [[60, 300], [540, 300], [520, 322], [80, 322]],
  };
  const KITA_ORTA = { "Kuzey Amerika": [110, 75], "Güney Amerika": [152, 205], "Avrupa": [295, 68], "Afrika": [305, 165], "Asya": [450, 85], "Avustralya": [505, 235], "Antarktika": [300, 315] };
  const OKY_YER = { "Büyük Okyanus": [570, 175], "Atlas Okyanusu": [215, 150], "Hint Okyanusu": [400, 225], "Arktik Okyanusu": [300, 14], "Antarktik Okyanusu": [300, 290] };
  function dunya({ kita = {}, okyanus = {}, ekvator = true } = {}) {
    const W = 620, H = 330;
    let ic = `<rect class="g-yumusak" x="0" y="0" width="${W}" height="${H}" rx="8"/>`;
    if (ekvator) ic += `<line class="g-cizgi" stroke-dasharray="6 5" x1="0" x2="${W}" y1="160" y2="160"/>` + G.yazi(6, 154, "Ekvator", { a: "start", k: 1 });
    for (const [ad, pts] of Object.entries(KITA)) {
      ic += `<polygon class="g-b g-cizgi" fill-opacity="0.75" stroke-width="1.5" points="${pts.map(p => p.join(",")).join(" ")}"/>`;
      if (kita[ad]) ic += G.yazi(KITA_ORTA[ad][0], KITA_ORTA[ad][1] + 5, kita[ad], { b: 1 });
    }
    for (const [ad, t] of Object.entries(okyanus)) ic += G.yazi(OKY_YER[ad][0] - (ad === "Büyük Okyanus" ? 25 : 0), OKY_YER[ad][1], t, { b: 1 });
    return G.svg(W, H, ic, "şematik dünya haritası");
  }
  /* Mahalle krokisi: iki cadde kesişir, köşelerde yapılar; sağ üstte kuzey oku */
  function kroki(adlar) {
    const W = 460, H = 300; let ic = `<rect class="g-ince g-bos" x="20" y="20" width="360" height="260"/>`;
    ic += `<rect class="g-ince g-yumusak" x="20" y="135" width="360" height="30"/><rect class="g-ince g-yumusak" x="185" y="20" width="30" height="260"/>`;
    const k = [[30, 30], [225, 30], [30, 175], [225, 175]];
    adlar.forEach((ad, i) => { ic += `<rect class="g-b g-cizgi" fill-opacity="0.6" x="${k[i][0]}" y="${k[i][1]}" width="145" height="95" rx="6"/>` + G.yazi(k[i][0] + 72, k[i][1] + 53, ad, { b: 1 }); });
    ic += G.ok(420, 120, 420, 50) + G.yazi(420, 40, "K", { b: 1 });
    return G.svg(W, H, ic, "mahalle krokisi: " + adlar.join(", "));
  }

